rmSync(join(repo, "node_modules"), { recursive: true });
symlinkSync(join(REPO_ROOT, "node_modules"), join(repo, "node_modules"));
write(repo, ".gitignore", "node_modules\n");

if (basename(hooksDir) === ".githooks") {
  console.warn(
    `install-git-hooks: core.hooksPath points at ${hooksDir}, so every worktree runs that checkout's hooks; nothing installed. Unset core.hooksPath and re-run npm install`
  );
  return;

const hooksPathScope = () => {
  try {
    return git("config", "--show-scope", "--get", "core.hooksPath").split("\t")[0];
  } catch {
    return null;

const res = runHook();

assert.equal(res.status, 1, res.stdout + res.stderr);
assert.equal(readFileSync(join(repo, "frontend", "src", "app.ts"), "utf8"), "staged\nunstaged\n");
assert.equal(git(repo, "show", ":frontend/src/app.ts"), "staged");
